  return skills.filter(skill=>{const display=localizedSkill(skill);return (!ui.category||skill.category===ui.category)&&(!query||`${display.name} ${display.description} ${display.category} ${skill.name} ${skill.description} ${skill.category}`.toLowerCase().includes(query));});
