function activeChatCommand(){const project=state.projects.find(p=>p.id===commandContext.projectId);const command=commandContext.command;const label=command?t("使用 {skill}：{prompt}",{skill:commandContext.skill.id,prompt:command.prompt}):commandContext.label;return buildChatCommand({label,project,material:$('#command-material').value,language:lang()});}
function updateCommandPreview(){$('#command-preview').textContent=activeChatCommand();$('#activation-preview').textContent=activationPrompt($('#command-client').value,lang());}
async function copyCommand(activation){const ok=await copyText(activation?activationPrompt($('#command-client').value,lang()):activeChatCommand());$('#command-feedback').textContent=ok?t("已复制。发送到打开本项目的 AI 对话中执行，写入完成后网页自动同步。"):t("请手动选中上方指令并复制。");}

async function copyText(text){try{await navigator.clipboard.writeText(text);toast(t("已复制到剪贴板"));return true;}catch{const area=document.createElement('textarea');area.value=text;area.className='clipboard-fallback';area.setAttribute('aria-label',t("待复制的内容"));const parent=[...document.querySelectorAll('dialog[open]')].at(-1)||document.body;parent.append(area);area.select();try{const ok=document.execCommand('copy');if(!ok)throw new Error('copy');toast(t("已复制到剪贴板"));return true;}catch{toast(t("浏览器未允许自动复制，请手动选择内容复制。"),true);return false;}finally{area.remove();}}}

async function handleAction(event){const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const {action,collection,id,view}=button.dataset;try{switch(action){case'assistant-shortcut':assistantWorkspace.startAction(assistantActions[Number(button.dataset.shortcut)]||'progress',{projectId:ui.projectId,command:getChatShortcuts()[Number(button.dataset.shortcut)]?.label});go('assistant');break;case'navigate':go(view);break;case'new':if(ui.view==='guidance'&&ui.guidanceTab==='reviews')focusAdviceForm();else openEditor(currentCollection());break;case'advice-import':openAdviceImport();break;case'new-record':openEditor(collection,null,button.dataset.status?{status:button.dataset.status}:{});break;case'edit':openEditor(collection,id);break;case'detail':openDetail(collection,id);break;case'delete':deleteRecord(collection,id);break;case'close-dialog':{const dialog=button.closest('dialog');if(dialog?.id==='editor-dialog'){if(editorContext?.busy){toast(t("正在保存，请稍候。"));break;}pendingCollection=null;}dialog?.close();break;}case'add-section':$('#section-editor').insertAdjacentHTML('beforeend',sectionRow());$('#section-editor .section-editor-row:last-child input').focus();break;case'remove-section':button.closest('.section-editor-row').remove();break;case'complete-task':{const task=findRecord('tasks',id);if(task)openEditor('tasks',id,{status:'done'});break;}case'meeting-task':{const meeting=findRecord('meetings',id);if(meeting)openEditor('tasks',null,{projectId:meeting.projectId,meetingId:meeting.id});break;}case'select-project':ui.projectId=id;updateProjectSelect();go('overview');break;case'guidance-tab':ui.guidanceTab=button.dataset.tab;ui.query='';ui.status='';renderHeading();renderToolbar();renderBody();break;case'reset-filter':ui.query='';ui.status='';ui.category='';if(ui.view==='projects')ui.projectId='';updateProjectSelect();renderToolbar();renderBody();break;case'report':await openReport();break;case'copy-report':await copyText(reportMarkdown);break;case'download-report':downloadText(reportMarkdown,`research-weekly-${ui.projectId||'all'}-${today()}.md`,'text/markdown;charset=utf-8');break;case'data':openData();break;case'export':await exportData();break;case'import':await runImport();break;case'clear-demo':clearDemo();break;case'skill':await openSkill(id);break;case'copy-skill':{const skill=skills.find(s=>s.id===id);if(skill)await copyText(skillPrompt(skill));break;}case'chat-command':openCommand(Number(button.dataset.shortcut));break;case'skill-command':openSkillCommand(id,button.dataset.command);break;case'copy-command':await copyCommand(false);break;case'copy-activation':await copyCommand(true);break;case'retry':await refresh(true);break;case'retry-skills':await loadSkills();break;}}catch(error){toast(error.message||t("操作未完成，请重试。"),true);}}
function handleChange(event){const target=event.target;if(target.id==='advice-project'){if(!adviceDraft.busy&&!adviceDraft.uncertain){adviceDraft.projectId=target.value;adviceDraft.error='';}return;}if(target.id==='review-import-file'){void importAdviceFile(target.files[0]);return;}if(target.id==='language-select'){changeLanguage(target.value);return;}if(target.id==='command-client'){updateCommandPreview();return;}if(target.id==='command-project'){commandContext.projectId=target.value;updateCommandPreview();return;}if(target.id==='project-select'){ui.projectId=target.value;renderNavigation();renderBody();}if(target.id==='status-filter'){ui.status=target.value;renderBody();}if(target.id==='category-filter'){ui.category=target.value;renderBody();}if(target.id==='field-projectId')updateRelations();if(target.id==='field-status')updateStatusRequirements();if(target.id==='import-file')void previewImport(target.files[0]);}
async function handleSubmit(event){if(event.target.id==='advice-form')return generateAdvice(event);if(event.target.id==='record-form')return saveRecord(event);if(event.target.id==='confirm-form'){event.preventDefault();const button=$('#confirm-submit');if(button.disabled)return;button.disabled=true;try{if(confirmAction)await confirmAction();$('#confirm-dialog').close();confirmAction=null;}catch(error){$('#confirm-error').textContent=error.message;$('#confirm-error').hidden=false;}finally{button.disabled=false;}}}
function init(){translateShell();initAppearance({language:lang(),onStorageError:()=>toast(t('已切换风格；当前浏览器无法保存偏好。'))});const date=new Date();$('#top-date').textContent=new Intl.DateTimeFormat(locale(),{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(date);$('#editor-dialog').addEventListener('cancel',event=>{if(editorContext?.busy){event.preventDefault();return;}pendingCollection=null;});document.addEventListener('click',handleAction);document.addEventListener('change',handleChange);document.addEventListener('submit',handleSubmit);document.addEventListener('input',event=>{if(event.target.id==='advice-focus'){if(!adviceDraft.busy&&!adviceDraft.uncertain){adviceDraft.projectId=adviceProjectId();adviceDraft.focus=event.target.value;}return;}if(event.target.id==='command-material'){updateCommandPreview();return;}if(event.target.id==='search-input'){ui.query=event.target.value;renderBody();}});window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main').focus();return;}navigate(location.hash.slice(1));});document.addEventListener('visibilitychange',()=>{if(!document.hidden)void refresh();});navigate(location.hash.slice(1)||'overview');restoreViewState();void refresh();void loadSkills();setInterval(()=>{if(!document.hidden)void refresh();},5000);}
init();
